export class TouchControls{
 constructor(onAction,onLook,onThrowPower=()=>{}){
  this.enabled=matchMedia('(pointer:coarse)').matches;this.onAction=onAction;this.mx=this.mz=0;this.fire=this.aim=false;this.stance='stand';this.pointer=this.lookPointer=null;this.vehicleMode=false;this.drive={left:0,right:0,throttle:0,brake:0};this.pointers=new Map();this.visible=false;this.driveVisible=false;document.body.classList.toggle('touch-device',this.enabled);const $=id=>document.getElementById(id);
  const finish=(id,cancel=false)=>{const held=this.pointers.get(id);if(!held)return;this.pointers.delete(id);held.element.classList.remove('held');held.release(cancel);try{if(held.element.hasPointerCapture(id))held.element.releasePointerCapture(id);}catch{}onAction('input-neutral');};
  this.releasePointer=finish;
  const bind=(element,start,move,end=()=>{})=>{element.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();if([...this.pointers.values()].some(p=>p.element===element))return;const state={element,release:cancel=>end(e.pointerId,cancel)};this.pointers.set(e.pointerId,state);start(e);try{element.setPointerCapture(e.pointerId);}catch{finish(e.pointerId,true);}});element.addEventListener('pointermove',e=>{if(this.pointers.get(e.pointerId)?.element!==element)return;e.preventDefault();if(e.pointerType==='mouse'&&e.buttons===0){finish(e.pointerId,true);return;}move?.(e);});element.addEventListener('lostpointercapture',e=>finish(e.pointerId,true));};
  for(const name of['pointerup','pointercancel'])window.addEventListener(name,e=>finish(e.pointerId,name!=='pointerup'),true);
  window.addEventListener('touchend',e=>{if(e.touches.length===0&&this.pointers.size)this.reset();},{passive:true});window.addEventListener('touchcancel',()=>this.reset(),{passive:true});for(const name of['blur','pagehide','orientationchange'])window.addEventListener(name,()=>this.reset());document.addEventListener('visibilitychange',()=>{if(document.hidden)this.reset();});
  for(const[id,field]of[['drive-left','left'],['drive-right','right'],['drive-accelerate','throttle'],['drive-brake','brake']]){const button=$(id);bind(button,()=>{this.drive[field]=1;button.classList.add('held');},null,()=>this.drive[field]=0);}
  let driverX=0,driverY=0;bind($('drive-look'),e=>{driverX=e.clientX;driverY=e.clientY;},e=>{onLook(e.clientX-driverX,e.clientY-driverY);driverX=e.clientX;driverY=e.clientY;});$('drive-exit').onclick=()=>onAction('interact');
  if(!this.enabled)return;const stick=$('joystick'),knob=$('stick-knob'),zone=$('touch-look');
  const update=e=>{const b=stick.getBoundingClientRect(),radius=Math.max(30,b.width*.35),x=(e.clientX-b.left-b.width/2)/radius,y=(e.clientY-b.top-b.height/2)/radius,n=Math.max(1,Math.hypot(x,y));this.mx=x/n;this.mz=-y/n;knob.style.transform=`translate(${this.mx*35}px,${-this.mz*35}px)`;};
  bind(stick,e=>{this.pointer=e.pointerId;update(e);},update,()=>{this.pointer=null;this.mx=this.mz=0;knob.style.transform='';});
  bind(zone,e=>{this.lookPointer=e.pointerId;this.lastX=e.clientX;this.lastY=e.clientY;},e=>{onLook(e.clientX-this.lastX,e.clientY-this.lastY);this.lastX=e.clientX;this.lastY=e.clientY;},()=>this.lookPointer=null);
  const fire=$('touch-fire');let fx=0,fy=0;bind(fire,e=>{fx=e.clientX;fy=e.clientY;this.fire=true;fire.classList.add('held');onAction('fire-start');},e=>{const x=e.clientX-fx,y=e.clientY-fy,gain=.32+Math.min(1.6,Math.hypot(x,y)*.045);if(this.throwable){onThrowPower(-y/150);onLook(x*gain,0);}else onLook(x*gain,y*gain);fx=e.clientX;fy=e.clientY;},(_,cancel)=>{this.fire=false;onAction(cancel?'fire-cancel':'fire-end');});
  $('touch-aim').addEventListener('pointerdown',e=>{e.preventDefault();this.aim=!this.aim;onAction('combat');$('touch-aim').classList.toggle('held',this.aim);});$('touch-stance').addEventListener('pointerdown',e=>{e.preventDefault();this.stance={stand:'crouch',crouch:'prone',prone:'stand'}[this.stance];onAction('stance:'+this.stance);});
  for(const[id,action]of[['touch-jump','jump'],['touch-loot','context'],['touch-switch','switch'],['touch-view','view']])$(id).addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();onAction(action);});
  $('touch-kit').onclick=()=>{this.reset();$('kit-tray').hidden=!$('kit-tray').hidden;};for(const b of document.querySelectorAll('[data-kit]'))b.onclick=()=>{onAction(b.dataset.kit);$('kit-tray').hidden=true;};$('minimap').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.classList.toggle('expanded');});document.addEventListener('touchmove',e=>{if(document.body.classList.contains('playing')&&!e.target.closest('.modal,dialog,.inventory,#throw-controls'))e.preventDefault();},{passive:false});document.addEventListener('dblclick',e=>{if(document.body.classList.contains('playing'))e.preventDefault();});
 }
 reset(){for(const id of [...this.pointers.keys()])this.releasePointer(id,true);this.mx=this.mz=0;this.fire=this.aim=false;document.getElementById('touch-aim')?.classList.remove('held');this.pointer=this.lookPointer=null;for(const k of Object.keys(this.drive))this.drive[k]=0;document.querySelectorAll('#vehicle-controls .held,#touch-fire.held').forEach(b=>b.classList.remove('held'));const knob=document.getElementById('stick-knob');if(knob)knob.style.transform='';this.onAction('input-neutral');}
 setVisible(value){const visible=!!value&&this.enabled&&!this.vehicleMode;if(this.visible&&!visible)this.reset();this.visible=visible;document.getElementById('touch-controls').hidden=!visible;if(!value)document.getElementById('kit-tray').hidden=true;}
 setSpectatorMode(mode,visible=true){if(this.spectator!==mode)this.reset();this.spectator=mode;document.body.classList.toggle('spectating',!!mode);const stick=document.getElementById('joystick');stick.hidden=!!mode&&mode!=='free';stick.querySelector('span').textContent=mode==='free'?'바라보는 방향으로 비행':'끝까지 밀면 달리기';if(mode&&this.enabled){document.getElementById('touch-controls').hidden=!visible;document.getElementById('kit-tray').hidden=true;}}
 setVehicleMode(value,visible=true){if(this.vehicleMode!==value||this.driveVisible&&!visible)this.reset();this.vehicleMode=value;this.driveVisible=value&&visible;document.getElementById('vehicle-controls').hidden=!this.driveVisible;if(value){document.getElementById('touch-controls').hidden=true;document.getElementById('kit-tray').hidden=true;}}
}
